UPDATE inventory
   SET available  = available - #{qty},
       reserved   = reserved + #{qty},
       updated_at = now()
 WHERE sku_id = #{skuId}
   AND available >= #{qty}

UPDATE inventory
   SET reserved   = reserved - #{qty},
       sold       = sold + #{qty},
       updated_at = now()
 WHERE sku_id = #{skuId}
   AND reserved >= #{qty}

UPDATE inventory
   SET available  = available + #{qty},
       reserved   = reserved - #{qty},
       updated_at = now()
 WHERE sku_id = #{skuId}
   AND reserved >= #{qty}

